물론입니다! 아래는 **Discord.js v14**를 기반으로, `ban`이라는 하나의 **슬래시 명령어**를 가진 간단한 Discord 봇 코드입니다. 이 명령어는 특정 유저를 서버에서 차단(ban)할 수 있으며, 명령어 등록과 처리 모두 포함되어 있습니다.

---

### ✅ 필요한 전제 조건

- Node.js v16 이상
- `discord.js` v14 설치 (`npm install discord.js`)
- 봇이 서버에 관리자 또는 차단 권한(`BAN_MEMBERS`)을 가지고 있어야 함
- 봇이 슬래시 명령어를 사용할 수 있도록 Discord 개발자 포털에서 설정 완료

---

### 📁 파일 구조 예시

```
bot/
├── index.js
└── commands/
    └── ban.js
```

---

## 1. `index.js` (메인 실행 파일)

```js
const { Client, Collection, GatewayIntentBits, REST, Routes } = require('discord.js');
const fs = require('fs');
const path = require('path');
require('dotenv').config(); // (선택) 토큰을 .env 파일에 저장하려면 사용

const client = new Client({
    intents: [
        GatewayIntentBits.Guilds,
        GatewayIntentBits.GuildMessages,
    ]
});

client.commands = new Collection();

// 명령어 폴더에서 슬래시 명령어 읽기
const commandsPath = path.join(__dirname, 'commands');
const commandFiles = fs.readdirSync(commandsPath).filter(file => file.endsWith('.js'));

for (const file of commandFiles) {
    const filePath = path.join(commandsPath, file);
    const command = require(filePath);
    if ('data' in command && 'execute' in command) {
        client.commands.set(command.data.name, command);
    } else {
        console.log(`[경고] ${filePath} 명령어는 data 또는 execute가 누락되어 있어 등록되지 않았습니다.`);
    }
}

// 슬래시 명령어 등록 (전역 또는 특정 서버에서)
const rest = new REST({ version: '10' }).setToken(process.env.TOKEN);

(async () => {
    try {
        console.log('슬래시 명령어를 등록하는 중입니다...');

        const commandsData = client.commands.map(cmd => cmd.data.toJSON());

        // 전역 명령어 등록 (모든 서버에 반영, 최대 1시간 소요)
        await rest.put(Routes.applicationCommands(process.env.CLIENT_ID), { body: commandsData });

        // 특정 서버에만 등록하려면 아래 주석 해제 (테스트용)
        // await rest.put(
        //     Routes.applicationGuildCommands(process.env.CLIENT_ID, process.env.GUILD_ID),
        //     { body: commandsData }
        // );

        console.log('슬래시 명령어 등록 완료!');
    } catch (error) {
        console.error('명령어 등록 중 오류 발생:', error);
    }
})();

// 봇 로그인
client.once('ready', () => {
    console.log(`${client.user.tag}이(가) 준비되었습니다!`);
});

// 슬래시 명령어 처리
client.on('interactionCreate', async interaction => {
    if (!interaction.isChatInputCommand()) return;

    const command = client.commands.get(interaction.commandName);

    if (!command) return;

    try {
        await command.execute(interaction);
    } catch (error) {
        console.error(error);
        await interaction.reply({ content: '명령어 실행 중 오류가 발생했습니다.', ephemeral: true });
    }
});

client.login(process.env.TOKEN);
```

