## 2. `commands/ban.js` (ban 명령어)

```js
const { SlashCommandBuilder } = require('discord.js');

module.exports = {
    data: new SlashCommandBuilder()
        .setName('ban')
        .setDescription('선택한 유저를 서버에서 차단합니다.')
        .addUserOption(option =>
            option.setName('유저')
                .setDescription('차단할 유저를 선택하세요.')
                .setRequired(true))
        .addStringOption(option =>
            option.setName('이유')
                .setDescription('차단 이유를 입력하세요.')
                .setRequired(false)),

    async execute(interaction) {
        const user = interaction.options.getUser('유저');
        const reason = interaction.options.getString('이유') || '이유가 제공되지 않았습니다.';
        const member = await interaction.guild.members.fetch(user.id).catch(() => null);

        // 권한 확인
        if (!interaction.member.permissions.has('BAN_MEMBERS')) {
            return interaction.reply({ content: '❌ 이 명령어를 사용할 권한이 없습니다.', ephemeral: true });
        }

        // 자기 자신 차단 방지
        if (user.id === interaction.user.id) {
            return interaction.reply({ content: '❌ 자기 자신을 차단할 수 없습니다.', ephemeral: true });
        }

        // 봇이 차단 권한이 있는지 확인
        if (!interaction.guild.members.me.permissions.has('BAN_MEMBERS')) {
            return interaction.reply({ content: '❌ 제게 차단할 권한이 없습니다.', ephemeral: true });
        }

        // 대상 멤버가 존재하고, 서버 등급이 봇보다 높지 않은지 확인
        if (member && member.permissions.has('BAN_MEMBERS')) {
            return interaction.reply({ content: '❌ 이 유저는 관리자 권한이 있어 차단할 수 없습니다.', ephemeral: true });
        }

        // 차단 시도
        try {
            await interaction.guild.members.ban(user, { reason });
            await interaction.reply({
                content: `✅ ${user.tag} 님이 성공적으로 차단되었습니다.\n이유: ${reason}`
            });
        } catch (error) {
            console.error(error);
            await interaction.reply({
                content: '❌ 유저를 차단하는 데 실패했습니다. 봇의 권한이나 유저 상태를 확인해 주세요.',
                ephemeral: true
            });
        }
    }
};
```

---

### 🔧 `.env` 파일 (선택)

```env
TOKEN=your_bot_token_here
CLIENT_ID=your_bot_client_id_here
GUILD_ID=your_server_guild_id_here (테스트용)
```

---

### 🚀 실행 방법

```bash
node index.js
```

봇이 시작되면 `ban` 명령어가 등록되고, 디스코드에서 `/ban`으로 사용 가능합니다.

---

### 📝 예시 사용법

```
/ban 유저:@User#1234 이유:스팸 행위
```

---

### ⚠️ 주의사항

- 슬래시 명령어는 **전역 등록 시 최대 1시간까지 캐싱됨** → 빠른 테스트를 원하면 `GuildCommand` 방식 추천
- 봇에 `BAN_MEMBERS` 권한이 부여되어 있어야 함
- `.env`에 토큰 저장 시 `.gitignore`에 `.env` 추가할 것

